    public List listarTarifasTasaAnual() {
        //TIPO UNIDAD MEDIDA =20
    String sql = "SELECT f19_codigo,f19_concepto,f19_valor,f19_fechaDesde,f19_fechaHasta,f19_estado,f20_concepto.f20_nombre,F19_producto " + 
    " from f19_tarifario inner join f20_concepto " + 
    " on f19_concepto = f20_codigo " + 
    " inner join f31_productos " + 
    " on f31_codigo = f19_producto " + 
    " where f19_estado = 'A' and f19_concepto = 3 and f31_cronograma = 'A REBATIR'" ;
     
        try{   
            return jdbcTemplate.query(sql, new TarifarioRebatirMapper());  
            
        } catch (final EmptyResultDataAccessException e) {
            return null;
        }
    }
    
    protected class TarifarioRebatirMapper implements RowMapper {
        public Object mapRow(ResultSet rs, int rowNum) throws SQLException {
            //Establecer los atributos en la entidad CuentaBean
            TarifarioBean puesto = new TarifarioBean();
            puesto.setCodigo((rs.getString(1)));
            puesto.setConcepto(rs.getString(2)); 
            puesto.setValor(rs.getString(3));
            puesto.setFechaDesde(pasaFecha(rs.getString(4)));
            puesto.setFechaHasta(pasaFecha(rs.getString(5)));
            puesto.setEstado(rs.getString(6));
            String producto = rs.getString(8);
            puesto.setProducto(producto);

            puesto.setStrConcepto(rs.getString(7));          
      
            return puesto;
        }
    }
    
    

