    protected class ProductoMapper implements RowMapper {
    public Object mapRow(ResultSet rs, int rowNum) throws SQLException {
    //Establecer los atributos en la entidad CuentaBean
    ProductoBean puesto = new ProductoBean();
    puesto.setCodigo((rs.getString(1)));
    puesto.setNombre(rs.getString(2));
    puesto.setCronograma(rs.getString(3)); 
    puesto.setMoneda(rs.getString(4));
    puesto.setMaxCuotas((rs.getString(5)));
    puesto.setMontoMin((rs.getString(6)));
    puesto.setMontoMax((rs.getString(7)));
    puesto.setConGarante((rs.getString(8)));
    puesto.setEstado(rs.getString(9));      
    puesto.setPrioridad(rs.getString(10));
    return puesto;
    }
    }
    
