    public double calculaAportaciones(double montoD, double aportacionP, 
                                      String socio) {
        double mf = 0;
        SocioBean sociob = getSocioporCliente(socio);
        if (sociob != null) {
            double s = Double.parseDouble(sociob.getSobregiro());
            if (s == 0) {
                if (montoD > aportacionP) {
                    mf = montoD - aportacionP;
                }

                if (montoD < aportacionP) {
                    mf = montoD;
                }
            }
        }
        return mf;
    }

