    protected class DescuentosMapper implements RowMapper {
        public Object mapRow(ResultSet rs, int rowNum) throws SQLException {
            System.out.println("socio" + rs.getString(1));
            DecimalFormatSymbols dfs = new DecimalFormatSymbols();
            dfs.setDecimalSeparator('.');
            dfs.setGroupingSeparator(',');
            DecimalFormat df1 = new DecimalFormat("#0.00", dfs);
            df1.setGroupingSize(3);

            AportacionBean bean = new AportacionBean();
            //socio         

            String tipo = rs.getString(20);


            //  String socio = rs.getString(1);
            Util helper = Util.getInstance();
            StringBuffer data = new StringBuffer("");
            
            String socio = rs.getString(1);
            
            if(socio.equals("333131")) {
                System.out.println("test");
            }

            if (tipo.equals("ACTIVO")) {
                data.append(helper.ConvertNumericAString(rs.getString(1), 7));
            } else {
                data.append(helper.ConvertNumericAString(rs.getString(1), 10));
            }
            //socio.setF01Cliente(data.toString());
            bean.setSocio(data.toString());


            double ap2 = rs.getDouble(12);
            //  bean.setAportacionP(String.valueOf(ap2));

            String ap4 = String.valueOf(df1.format(ap2));


            String nueva2 = "0";
            String da = "00";

            int p3221 = String.valueOf(ap4).indexOf(".");
            if (p3221 != -1) {
                nueva2 = String.valueOf(ap4).substring(0, p3221);
                da = String.valueOf(ap4).substring(p3221 + 1);
            }
            bean.setAportacionP(String.valueOf(nueva2));
            bean.setDecimalAporte(String.valueOf(da));


            double inp22 = rs.getDouble(4);
            double inp2 = rs.getDouble(5);
            //  double ss = inp22 + inp2; 
            double ss = rs.getDouble(15);
            String nueva = "0";
            String dp = "00";


            String ss2 = String.valueOf(df1.format(ss));


            int p322 = String.valueOf(ss2).indexOf(".");
            if (p322 != -1) {
                nueva = String.valueOf(ss2).substring(0, p322);
                dp = String.valueOf(ss2).substring(p322 + 1);
            }
            bean.setAxu(nueva);
            //  bean.setDecimalPrestam(dp);


            double montoD = rs.getDouble(16);

            double mf = 0;

            if (ap2 > 0) {

                montoD = montoD - ap2;

                if (montoD >= 0) {

                    bean.setAportacionD(String.valueOf(ap2));
                }

            }

            //fin descuento por aportacion   

            if (montoD >= 0) {
                double inp = rs.getDouble(5);

                if (inp > 0) {
                    bean.setInteresP(String.valueOf(inp));

                    montoD = montoD - inp;
                    bean.setInteresA(String.valueOf(inp));
                }
            }


            if (montoD >= 0) {
                double mp = rs.getDouble(8);
                if (mp > 0) {
                    bean.setMoraP(String.valueOf(mp));

                    montoD = montoD - mp;
                    bean.setMoraA(String.valueOf(mp));
                }
            }

            double otro = rs.getDouble(11);
            bean.setOtrosP(String.valueOf(otro));


            montoD = montoD - otro;


            double otro2 = rs.getDouble(18);

            bean.setOtrosP2(String.valueOf(otro2));

            montoD = montoD - otro2;

            if (montoD > 0) {
                bean.setAmortizacion(String.valueOf(montoD));
            }

            double mA = rs.getDouble(16);

            bean.setTotalA(String.valueOf(mA));


            double td2 = rs.getDouble(15);

            String s = String.valueOf(df1.format(td2));
            String n = "";
            dp = "00";
            int p32 = s.indexOf(".");
            if (p32 != -1) {
                n = s.substring(0, p32);
                //agregue hoy
                dp = s.substring(p32 + 1);
            }

            System.out.println("v:" + n);

            //  double td21 = rs.getDouble(4)+ rs.getDouble(5) +rs.getDouble(12);
            double td21 = rs.getDouble(15);
            if(td21 > 3000) {
                     td21 = 3000.00;
                     }
            String s2 = String.valueOf(df1.format(td21));
            String n2 = "";
            dp = "00";
            int p328 = s2.indexOf(".");
            if (p328 != -1) {
                n2 = s2.substring(0, p328);
                //agregue hoy
                dp = s2.substring(p328 + 1);
            }


            bean.setDecimalPrestam(dp);

            bean.setTotalP(String.valueOf(n2));

            //agregue hoy


            double td = rs.getDouble(17);

            bean.setTotalD(String.valueOf(td));


            return bean;

        }
    }


    public List listarDescuentos2(String periodo, String ano, String tipo, 
                                  String centro) {
        //TIPO UNIDAD MEDIDA =20
        sql = "SELECT * FROM `sacs`.`f24_descuentos` where ";

        if (!periodo.equals("")) {
            sql = sql + "  MONTH(f24_periodo)  = '" + periodo + "'";

        }

        if (!ano.equals("0")) {
            sql = sql + " and YEAR(f24_periodo)  = '" + ano + "'";

        }

        if (!tipo.equals("0")) {
            sql = sql + " and f24_tipo  = '" + tipo + "'";

        }
        if (!centro.equals("0")) {
            sql = sql + " and f24_centro  = " + centro;

        }

        sql = sql + " and f24_producto  = 1 ";

        sql = sql + " and f24_montoP > 0  ";

        sql = sql + " order by f24_socio asc ";
        try {
            System.out.println(sql);
            return jdbcTemplate.query(sql, new DescuentosMapper0());

        } catch (final EmptyResultDataAccessException e) {
            return null;
        }
    }


