    public List listarAportacionesSocio2019(String codigo) {
        //TIPO UNIDAD MEDIDA =20
        String sql = "";

        sql = 
    "select (SELECT LPAD(f22_socio,7,'0')) as ccliente,f22_aportacion,f22_periodo,f22_aportacionP,f22_aportacionD,f22_fechaPago,f22_aportacion - f22_aportacionD as " + 
    " f22_diferencia2,CONCAT(personaCliente.`F01_APE_PAT`,' ',     personaCliente.`F01_APE_MAT`,' ' ,personaCliente. `F01_NOMB_PRI`,' ',     personaCliente.`F01_NOMB_SEG` ) AS cliente,  " + 
    " (select case when personaCliente.f01_CENTRO= 1 then 'BANCO DE LA NACION' " + 
    " when personaCliente.f01_CENTRO= 2 then 'F.E.B.A.N' " + 
    " when personaCliente.f01_CENTRO= 5 then 'NO SOCIO' " + 
    " when personaCliente.f01_CENTRO= 3 then 'AYUDA MUTUA' " + 
 
    "else 'OTRO' " + 
    "       end as FP ) AS CENTRO, " + 
    " personaCliente.f01_CONDICION AS CONDICION, (personaCliente.`F01_APORTACION` - personaCliente.`F01_APORTA_BASE`) as aporta2, personaCliente.`F01_APORTACION` as aporte from f22_aportes " + 

    "     inner join `sacs`.`f02_cliente` cliente " + 
    "     on '" + codigo +"' = cliente.`F02_ID_CLIENTE` " + 

    "     inner join " + 
    "     `sacs`.`f01_persona` personaCliente " + 
    "     on " + 
    "     sacs.personaCliente.f01_id_persona = sacs.cliente.f02_id_persona " + 
    " where f22_Socio = '" + codigo +"' and DATE(f22_periodo)  >= DATE(personaCliente.F01_FE_USUA_CREA) " + 
   
    " order by f22_periodo desc ";


        try {

            return jdbcTemplate.query(sql, new AportacionesMapper2019());

        } catch (final EmptyResultDataAccessException e) {
            return null;
        }
    }
    
    
