    protected class DescuentosMapper2 implements RowMapper {

        public Object mapRow(ResultSet rs, int rowNum) throws SQLException {

            DecimalFormatSymbols dfs = new DecimalFormatSymbols();
            dfs.setDecimalSeparator('.');
            dfs.setGroupingSeparator(',');
            DecimalFormat df1 = new DecimalFormat("###,###,##0.00", dfs);
            df1.setGroupingSize(3);

            //monto Abonado
            double mA = rs.getDouble(16);
            double aportacionS = 0;
            double interesS = 0;
            double moraS = 0;
            double resto = 0;
            double saldoA = 0;

            AportacionBean beanA = 
                getDescuento(new Integer(rs.getString(1)), rs.getString(2));
            if (beanA != null) {
                //aportacion sobregiro
                aportacionS = Double.parseDouble(beanA.getAportacionSS());
                interesS = Double.parseDouble(beanA.getInteresD());
                moraS = Double.parseDouble(beanA.getMoraD());
                saldoA = Double.parseDouble(beanA.getSaldo());
            }

            double aportep = rs.getDouble(12);
            double interesp = rs.getDouble(5);
            double morap = rs.getDouble(8);

            AportacionBean bean = new AportacionBean();

            Util helper = Util.getInstance();
            StringBuffer data = new StringBuffer("");
            data.append(helper.ConvertNumericAString(rs.getString(1), 7));
            bean.setSocio(data.toString());


            bean.setTotalA(String.valueOf(mA));
            bean.setTotalP(String.valueOf(rs.getString(15)));

            double otro = rs.getDouble(11);
            bean.setOtrosP(String.valueOf(otro));

            double otro2 = rs.getDouble(18);

            bean.setOtrosP2(String.valueOf(otro2));


            double ad = aportep + aportacionS;


            resto = mA - ad;

            if (resto > 0) {

                bean.setAportacionD(String.valueOf(ad));
            } else {
                bean.setAportacionD(String.valueOf(mA));
            }


            double ia = interesp + interesS;

            resto = resto - ia;

            if (resto > 0) {
                bean.setInteresD(String.valueOf(ia));

            }

            double ma = moraS + morap;

            resto = resto - ma;

            if (resto > 0) {
                bean.setMoraD(String.valueOf(ma));

            }

            if (resto > 0) {
                bean.setAmortizacion(String.valueOf(resto));
            }
            double saldo = 0;
            if (saldoA > resto) {
                saldo = saldoA - resto;
                bean.setSaldo(String.valueOf(saldo));
            }

            return bean;

        }
    }


