    public int getAportacionFinal2(String codigo) {
        String sql = 
            "            SELECT sum(`F01_APORTA_BASE`) " + "                                      FROM `sacs`.`f01_persona` , sacs.f12_familiar " + 
            "                                        where  sacs.f12_familiar.f12_id_persona   =  sacs.f01_persona.f01_id_persona " + 
            "                           and sacs.f12_familiar.f12_id_cliente = " + 
            codigo + " and F01_STDO_PERSN = 1 and f12_familiar.f12_id_tpo_parent < 11 ";

        System.out.println(sql);
        int value = this.jdbcTemplate.queryForInt(sql);
        return value;

    }


    public double getAportacionFinal(int codigo) {
        double suma = 0;

        List listado = listarFamiliares(String.valueOf(codigo));
        for (int i = 0; i < listado.size(); i++) {
            SocioBean fa = new SocioBean();
            fa = (SocioBean)listado.get(i);
            if (fa.getAportacion() != null && !fa.getAportacion().equals("")) {
                suma = Double.parseDouble(fa.getAportacion());
            }
        }

        return suma;


    }


