    public List getDepartamentos() {
        String query = 
            "SELECT DISTINCT(SUBSTRING(UBIGEO_CODIGO, 1, 2)) AS CODIGO, (UBIGEO_DISTRITO) AS DEPARTAMENTO " + 
            "FROM sacs.f05_ubigeo ORDER BY UBIGEO_DISTRITO ASC ";
        return jdbcTemplate.query(query, new DepasMapper());
    }

    protected class DepasMapper implements RowMapper {
        public Object mapRow(ResultSet rs, int rowNum) throws SQLException {
            //Establecer los atributos en la entidad CuentaBean


            TipoBean puesto = new TipoBean();
            puesto.setCodigo((rs.getString(1)));
            puesto.setNombre(rs.getString(2));
            return puesto;
        }
    }


    protected class DetaMapper implements RowMapper {
           public Object mapRow(ResultSet rs, int rowNum) throws SQLException {
               //Establecer los atributos en la entidad CuentaBean
               SocioBean puesto = new SocioBean();
               puesto.setTitulo((rs.getString(2)));
               puesto.setObs(rs.getString(3));
               puesto.setFechaBanco(rs.getString(4));
               puesto.setF01FeUsrReg(rs.getString(5));
               return puesto;
           }
       }

    public List getProvincias(String depa) {
        String query = 
            "SELECT DISTINCT(SUBSTRING(UBIGEO_CODIGO, 3, 2)) AS CODIGO, (UBIGEO_PROVINCIA) AS PROVINCIA FROM sacs.f05_ubigeo WHERE SUBSTRING(UBIGEO_CODIGO, 1, 2) = ? ORDER BY UBIGEO_PROVINCIA ASC ";
        Object[] params = new Object[] { depa };
        return jdbcTemplate.query(query, params, new ProvinciasMapper());
    }

    protected class ProvinciasMapper implements RowMapper {
        public Object mapRow(ResultSet rs, int rowNum) throws SQLException {
            //Establecer los atributos en la entidad CuentaBean
            TipoBean puesto = new TipoBean();
            puesto.setCodigo((rs.getString(1)));
            puesto.setNombre(rs.getString(2));
            return puesto;
        }
    }

    public List getDistritos(String depa, String prov) {
        String query = 
            "SELECT DISTINCT(SUBSTRING(UBIGEO_CODIGO, 5, 2)) AS CODIGO, (UBIGEO_DEPARTAMENTO) AS DISTRITO FROM sacs.f05_ubigeo WHERE SUBSTRING(UBIGEO_CODIGO, 3, 2) = ? AND SUBSTRING(UBIGEO_CODIGO, 1, 2) = ? ORDER BY UBIGEO_DEPARTAMENTO ASC";
        Object[] params = new Object[] { prov, depa };
        return jdbcTemplate.query(query, params, new DistritosMapper());
    }

    protected class DistritosMapper implements RowMapper {
        public Object mapRow(ResultSet rs, int rowNum) throws SQLException {
            //Establecer los atributos en la entidad CuentaBean
            TipoBean puesto = new TipoBean();
            puesto.setCodigo((rs.getString(1)));
            puesto.setNombre(rs.getString(2));
            return puesto;
        }
    }


