    protected class UbigeoMapper implements RowMapper {
        public Object mapRow(ResultSet rs, int rowNum) throws SQLException {
            //Establecer los atributos en la entidad CuentaBean
            UbigeoBean contacto = new UbigeoBean();
            contacto.setCodigo(rs.getString(4));
            contacto.setDistrito(rs.getString(1));
            contacto.setProvincia(rs.getString(2));
            contacto.setDepartamento(rs.getString(3));

            return contacto;
        }
    }

    public UbigeoBean getUbigeo(String distrito, String prov, String depa) {
        String codigo = "";
        codigo = depa.trim() + prov.trim() + distrito.trim();
        System.out.println(codigo);
        String sql = 
            "SELECT ubigeo_departamento, ubigeo_provincia, ubigeo_distrito, ubigeo_codigo " + 
            "  FROM f05_ubigeo where ubigeo_codigo =  ?";
        Object[] params = new Object[] { codigo };
        try {
            return (UbigeoBean)jdbcTemplate.queryForObject(sql, params, 
                                                           new UbigeoMapper());
        } catch (final EmptyResultDataAccessException e) {
            return null;
        }
    }


