    public String pasaFecha(String fecha) {
        if (fecha != null) {
            String ano = fecha.substring(0, 4);
            String mes = fecha.substring(5, 7);
            String dia = fecha.substring(8, 10);
            return dia + "/" + mes + "/" + ano;
        } else {
            return "";
        }
    }
    
