    public int calculaEdad(String fecha) {
        int age = 0;
        try {
            Calendar birth = new GregorianCalendar();
            Calendar today = new GregorianCalendar();

            int factor = 
                0; //to correctly calculate age when birthday has not been yet celebrated
            Date birthDate = new SimpleDateFormat("yyyy-MM-dd").parse(fecha);
            Date currentDate = new Date(); //current date

            birth.setTime(birthDate);
            today.setTime(currentDate);

            // check if birthday has been celebrated this year
            if (today.get(Calendar.DAY_OF_YEAR) < 
                birth.get(Calendar.DAY_OF_YEAR)) {
                factor = -1; //birthday not celebrated
            }
            age = today.get(Calendar.YEAR) - birth.get(Calendar.YEAR) + factor;

        } catch (ParseException e) {
            e.printStackTrace();
        }

        return age;
    }

