    public int incrementaChe(){
          String sql = 
               "select Max(f23_codigo) from sacs.f23_cheque";        
           
           int value = this.jdbcTemplate.queryForInt(sql);
           return value +1; 
       }  

    public int registrarCheque(ChequeBean socio) {
        int rs = 0;
        int id = incrementaChe();
        sql = 
"INSERT INTO sacs.f23_cheque " + "        (f23_codigo,f23_nombre,f23_monto,f23_montoLetras,f23_fecha,f23_cheque,f23_motivo,f23_centro,f23_condicion )" + 
  " VALUES " + "       (?, ?,?,?,?,?,  ?,?,?  )";

        Object[] params = 
            new Object[] { id, socio.getNombre(), socio.getMonto(), 
                           socio.getMontoLetras(), new Date(), 
                           socio.getCheque(), socio.getMotivo(), 
                           socio.getCentro(), socio.getCondicion() };

        rs = this.jdbcTemplate.update(sql, params);

        return id;
    }

    public boolean registrarClienteFamiliar(FamiliarBean socio) {
        int rs = 0;

        sql = 
"INSERT INTO sacs.f12_familiar " + "        ( `F12_ID_CLIENTE`,`F12_ID_PERSONA`,`F12_ID_TPO_PARENT`, `F12_STDO_PARENT` )" + 
  " VALUES " + "       (?, ?,?,?)";

        Object[] params = 
            new Object[] { socio.getCliente(), socio.getPersona(), 
                           socio.getParentesco(), 1 };

        rs = this.jdbcTemplate.update(sql, params);

        return (rs > 0 ? true : false);
    }


