	 protected class AportacionesMapper2019 implements RowMapper {
        public Object mapRow(ResultSet rs, int rowNum) throws SQLException {

            DecimalFormatSymbols dfs = new DecimalFormatSymbols();
                    dfs.setDecimalSeparator('.');
                    dfs.setGroupingSeparator(',');
                    DecimalFormat df1 = new DecimalFormat("#0.00", dfs);
                    df1.setGroupingSize(3);

            AportacionBean bean = new AportacionBean();


            //Util helper = Util.getInstance();
           // StringBuffer data = new StringBuffer("");
          //  data.append(helper.ConvertNumericAString(rs.getString(1), 7));
          //  bean.setSocio(data.toString());
          //  bean.setSocio(rs.getString(1));

            bean.setFecha(pasaFecha3(rs.getString(3)));
            bean.setAportacionP(String.valueOf(df1.format(rs.getDouble(4))));
            bean.setAportacionD(String.valueOf(df1.format(rs.getDouble(5))));
            bean.setAportacionSS(String.valueOf(df1.format(rs.getDouble(7))));
            if (rs.getString(6) != null) {
                bean.setFechaPago(pasaFecha(rs.getString(6)));
            }
      
            return bean;

        }
    }
	
	
	

