    protected class PrestamosMapper9 implements RowMapper {
        public Object mapRow(ResultSet rs, int rowNum) throws SQLException {
            PrestamoBean prestamo = new PrestamoBean();

            prestamo.setCuotas(rs.getString(1));

            prestamo.setImporte(rs.getString(2));
            if (rs.getString(4) != null) {
                prestamo.setSaldo(String.valueOf(rs.getDouble(4)));
            }
            if (rs.getString(5) != null) {
                prestamo.setFechaUP(pasaFecha(rs.getString(5)));
            }
            prestamo.setFechaR(pasaFecha(rs.getString(6)));
            prestamo.setCuotasPen(rs.getString(7));
            prestamo.setMora(rs.getString(8));
            prestamo.setOtros(rs.getString(9));
            prestamo.setOtros2(rs.getString(10));
            prestamo.setAportacion(rs.getString(11));
            prestamo.setNcuotas(rs.getString(13));
            prestamo.setIntereses(rs.getDouble(12));
            prestamo.setInteresReba(rs.getString(12));
            prestamo.setCodigo(rs.getString(14));
            prestamo.setGastosa(String.valueOf(rs.getDouble(15)));
            prestamo.setProducto(rs.getString(16));
            double i = rs.getDouble(3);
            double i2 = rs.getDouble(12);

            if (i2 < 5)
                prestamo.setInteres(String.valueOf(i));
            else
                prestamo.setInteres(String.valueOf(i2));


            return prestamo;
        }
    }


