    public List listarSociosPronostico(String centro, String c, 
                                       String horizonte) {
        //TIPO UNIDAD MEDIDA =20
        String sql = "";

        sql = 
"SELECT `F02_ID_CLIENTE` ,`F01_APORTACION`  FROM `sacs`.`f01_persona` inner join `sacs`.`f02_cliente` " + 
  " on sacs.f01_persona.f01_id_persona = sacs.f02_cliente.f02_id_persona where  f01_centro = ? and F01_STDO_PERSN = 1  and  F01_CONDICION = ?  order by F02_ID_CLIENTE asc";


        try {
            Object[] params = new Object[] { centro, c };
            return jdbcTemplate.query(sql, params, 
                                      new SocioMapperT2(horizonte));

        } catch (final EmptyResultDataAccessException e) {
            return null;
        }
    }


