        public boolean validaPeriodo2(String fecha, String fecha2){
        boolean flag = false;
            int puto = fecha.indexOf("/");
            int puto2 = fecha.lastIndexOf("/");
            String dia = fecha.substring(0,puto);
            String mes = fecha.substring(puto+1,puto2);
            String año = fecha.substring(puto2+1);
            
            int puto3 = fecha2.indexOf("/");
            int puto4 = fecha2.lastIndexOf("/");
            String dia2 = fecha2.substring(0,puto3);
            String mes2 = fecha2.substring(puto+1,puto4);
            String año2 = fecha2.substring(puto4+1);
            if(mes.equals(mes2)&& año.equals(año2)) flag = true;
            if(flag == true) {
            if(!dia.equals(dia2)) flag = true;
            else {
                flag = false;
            }
            }
        return flag;
        }
        
       
        
        
