    private void actualizaSaldos(String codigo, String cuotasPen, double totali, double mora, double saldoT, double totalsobre){
        DecimalFormatSymbols dfs = new DecimalFormatSymbols();
        dfs.setDecimalSeparator('.');
        dfs.setGroupingSeparator(',');
        DecimalFormat df1 = new DecimalFormat("#0.00", dfs);
        df1.setGroupingSize(3);   
        PrestamoBean prestamoMona = new   PrestamoBean();
        prestamoMona.setCodigo(codigo);
        prestamoMona.setCuotasPen(String.valueOf(cuotasPen));
        prestamoMona.setGastosa(String.valueOf(df1.format(totali)));
        prestamoMona.setGastosm(String.valueOf(df1.format(mora)));                
        prestamoMona.setSaldo(String.valueOf(df1.format(saldoT)));
        prestamoMona.setSobre(String.valueOf(df1.format(totalsobre)));
        actualizarPrestamoMonaS(prestamoMona);                          

    }
    
