    public int getMeses(String fecha,String fechaPrestamo){
    int diaF = 0;
    try{
    //String diaActual = getFechaActual2();
    String diaActual = fechaPrestamo;
    int diaA = new Integer(diaActual.substring(0,2));
    int mesA = new Integer(diaActual.substring(3,5));
    int diaD = new Integer(fecha.substring(0,2));
    int mesD = new Integer(fecha.substring(3,5));
    
        SimpleDateFormat f = new SimpleDateFormat("dd/MM/yyyy");
            Date d1 = f.parse(fechaPrestamo);
            Date d2 = f.parse(fecha);
    
    if(diaA >= 1 && diaA <= 25)
    {
    diaF = differenceInMonths(d1,d2);
    if(diaA>= diaD){
    diaF = diaF +1;
    }
    }
    if(diaA >25)
    {   
    diaF = differenceInMonths(d1,d2);
    //diaF = mesD - mesA -1;
    }
    }catch(Exception e){
    e.printStackTrace();
    }
    return diaF;
    }
        
    private static int differenceInMonths(Date d1, Date d2) {
        Calendar c1 = Calendar.getInstance();
        c1.setTime(d1);
        Calendar c2 = Calendar.getInstance();
        c2.setTime(d2);
        int diff = 0;
        if (c2.after(c1)) {
            while (c2.after(c1)) {
                c1.add(Calendar.MONTH, 1);
                if (c2.after(c1)) {
                    diff++;
                }
            }
        } else if (c2.before(c1)) {
            while (c2.before(c1)) {
                c1.add(Calendar.MONTH, -1);
                if (c1.before(c2)) {
                    diff--;
                }
            }
        }
        return diff;
    }

