    protected class CronogramaMapper implements RowMapper {
        public Object mapRow(ResultSet rs, int rowNum) throws SQLException {
            CronogramaBean mov = new CronogramaBean();
            mov.setId(rs.getString(1));
            mov.setFechaStr(pasaFecha(rs.getString(2)));
            mov.setAmortizacion(rs.getString(3));
            mov.setInteres(rs.getString(4));
            mov.setCuota(rs.getString(5));
            mov.setResto(rs.getString(6));
            mov.setCta(rs.getString(7));
            mov.setTamortizacion(rs.getString(8));
            mov.setEstado(rs.getString(9));
            return mov;
        }
    }


    public CronogramaBean getCronograma(String codigo) {

        String sql = 
            "select f17_ncuota,f17_fecha,f17_capital,f17_interes,f17_total,f17_saldo,f17_cta,f17_totalA,f17_estado from  f17_cuotasprestamo where f17_prestamo = ? and  f17_ncuota = 1  GROUP by f17_ncuota ";
        Object[] params = new Object[] { codigo };
        try {
            return (CronogramaBean)jdbcTemplate.queryForObject(sql, params, 
                                                               new CronogramaMapper());
        } catch (final EmptyResultDataAccessException e) {
            return null;
        }

    }


    protected class SocioMapperT2 implements RowMapper {
        String h = "";

        public SocioMapperT2(String horizonte) {
            h = horizonte;
        }

        public Object mapRow(ResultSet rs, int rowNum) throws SQLException {

            int total = 0;
            double suma = 0;

            double totali = 0;
            double totalimp = 0;
            double totalc = 0;
            double saldoT = 0;

            int cuotasPen = 0;
            int ho = 0;
            ho = new Integer(h);

            AportacionBean socio = new AportacionBean();

            Util helper = Util.getInstance();
            StringBuffer data2 = new StringBuffer("");
            data2.append(helper.ConvertNumericAString(rs.getString(1), 7));
            socio.setSocio(data2.toString());


            String mb = rs.getString(2);

            String c = "0";


            if (mb != null) {
                suma = Double.parseDouble(mb);
            }

            String s = String.valueOf(suma);
            int p32 = s.indexOf(".");
            if (p32 != -1) {
                s = s.substring(0, p32);

                socio.setAportacionP(String.valueOf(s));

                String i = "0";
                String impo = "0";
                double saldo = 0;
                List listadoP = 
                    getPrestamosDescuentos(new Integer(rs.getString(1)));
                if (listadoP != null && listadoP.size() > 0) {
                    for (int h = 0; h < listadoP.size(); h++) {
                        PrestamoBean pres = (PrestamoBean)listadoP.get(h);

                        if (pres != null) {
                            if (pres.getFechaUP() != null) {
                                if (!pres.getFechaUP().equals(pres.getFechaR())) {
                                    saldo = 
                                            Double.parseDouble(pres.getSaldo());

                                    saldoT = saldoT + saldo;

                                    cuotasPen = 
                                            new Integer(pres.getCuotasPen());

                                    i = pres.getInteres();
                                    totali = totali + Double.parseDouble(i);


                                    impo = pres.getImporte();

                                    totalimp = 
                                            totalimp + Double.parseDouble(impo);


                                    c = pres.getCuotas();

                                    totalc = totalc + Double.parseDouble(c);


                                }
                            }
                        }
                    }
                }
                //fin del prestamo  


                if (cuotasPen == 0) {
                    socio.setTotalP(String.valueOf(0));
                    socio.setInteresP(String.valueOf(0));
                    socio.setAmortizacion(String.valueOf(0));

                }

                if (cuotasPen > 0 && cuotasPen <= ho) {

                    totalc = (totalc * new Double(cuotasPen));
                    totali = (totali * new Double(cuotasPen));
                    totalimp = (totalimp * new Double(cuotasPen));
                }

                if (cuotasPen > ho) {

                    totalc = (totalc * ho);
                    totali = (totali * ho);
                    totalimp = (totalimp * ho);
                }

                int p6 = String.valueOf(totali).indexOf(".");
                if (p6 != -1) {
                    i = String.valueOf(totali).substring(0, p6);
                }

                int p322 = String.valueOf(totalimp).indexOf(".");
                if (p322 != -1) {
                    impo = String.valueOf(totalimp).substring(0, p322);
                }


                int p3 = String.valueOf(totalc).indexOf(".");
                if (p3 != -1) {
                    c = String.valueOf(totalc).substring(0, p3);
                }


                socio.setSaldo(String.valueOf(saldoT));
                socio.setInteresP(String.valueOf(i));
                socio.setAmortizacion(String.valueOf(impo));

            }

            total = new Integer(c);


            socio.setTotalP(String.valueOf(total));

            return socio;

        }
    }


