    public String getFecha(String fecha) {
        String nuevaFecha = null;
        try {
            int puto = fecha.indexOf("/");
            int puto2 = fecha.lastIndexOf("/");
            String dia = fecha.substring(0, puto);
            String mes = fecha.substring(puto + 1, puto2);
            String año = fecha.substring(puto2 + 1);
            nuevaFecha = año + "-" + mes + "-" + dia;
        } catch (Exception e) {
            e.printStackTrace();
        }
        return nuevaFecha;
    }


    protected class ChequeMapper implements RowMapper {
           public Object mapRow(ResultSet rs, int rowNum) throws SQLException {


               ChequeBean socio = new ChequeBean();

               socio.setCodigo(rs.getString(1));
               socio.setNombre(rs.getString(2));
               socio.setMonto(rs.getString(3));
               socio.setMontoLetras(rs.getString(4));
               if (rs.getString(5) != null) {
                   socio.setFecha(pasaFecha(rs.getString(5)));
               }
               socio.setCheque(rs.getString(6));
               socio.setMotivo(rs.getString(7));

               String ct = rs.getString(8);
               
               socio.setCentro(ct);
               if (ct != null && ct.equals("1")) {
                   socio.setStrCentro("BANCO DE LA NACION");
               }

               if (ct != null && ct.equals("2")) {
                   socio.setStrCentro("FEBAN");
               }

               if (ct != null && ct.equals("3")) {
                   socio.setStrCentro("Ayuda Mutua");
               }

               if (ct != null && ct.equals("4")) {
                   socio.setStrCentro("Otro");
               }
               
               if (ct != null && ct.equals("5")) {
                   socio.setStrCentro("NO SOCIO");
               }

               socio.setCondicion(rs.getString(9));

               return socio;
           }
       }


    protected class AportacionesMapper implements RowMapper {
        public Object mapRow(ResultSet rs, int rowNum) throws SQLException {

            DecimalFormatSymbols dfs = new DecimalFormatSymbols();
                    dfs.setDecimalSeparator('.');
                    dfs.setGroupingSeparator(',');
                    DecimalFormat df1 = new DecimalFormat("#0.00", dfs);
                    df1.setGroupingSize(3);

            AportacionBean bean = new AportacionBean();


            //Util helper = Util.getInstance();
           // StringBuffer data = new StringBuffer("");
          //  data.append(helper.ConvertNumericAString(rs.getString(1), 7));
          //  bean.setSocio(data.toString());
            bean.setSocio(rs.getString(1));

            bean.setFecha(pasaFecha3(rs.getString(2)));
            bean.setAportacionP(String.valueOf(df1.format(rs.getDouble(3))));
            bean.setAportacionD(String.valueOf(df1.format(rs.getDouble(4))));
            bean.setAportacionSS(df1.format(rs.getDouble(7)- rs.getDouble(4)));
            if (rs.getString(6) != null) {
                bean.setFechaPago(pasaFecha(rs.getString(6)));
            }
            bean.setAportacion(String.valueOf(rs.getDouble(7)));
            bean.setId(rs.getLong(8));
            return bean;

        }
    }

