    private AportacionBean getSogregiroFP(AportacionBean bean, String soc) {
    double sobregiroo = 0;      
        DecimalFormatSymbols dfs = new DecimalFormatSymbols();
        dfs.setDecimalSeparator('.');
        dfs.setGroupingSeparator(',');
        DecimalFormat df1 = new DecimalFormat("#0.00", dfs);
        df1.setGroupingSize(3);
    List listadoP0 = 
        getPrestamosDescuentosProductoPatrias(new Integer(soc));
    if (listadoP0 != null && listadoP0.size() > 0) {
        for (int k = 0; k < listadoP0.size(); k++) {
            PrestamoBean prestamo = (PrestamoBean)listadoP0.get(k);
            sobregiroo = Double.parseDouble(prestamo.getAportacion());
            double gadaee = 0;
            double moraaee =0;
            
            if (prestamo.getGastosa() != null) {
                gadaee = Double.parseDouble(prestamo.getGastosa());
            }
            
            if (prestamo.getMora() != null) {
                moraaee = Double.parseDouble(prestamo.getMora());
            }
            
            
            if (sobregiroo < 1) {
                sobregiroo = (double)Math.round(sobregiroo);                           
            }

            if (sobregiroo < 20) {
                sobregiroo = 0;

            }
            
            double yu = 0;
            yu = 0.02 * sobregiroo;
            
            bean.setOtrosP2(String.valueOf(df1.format(sobregiroo)));
            bean.setOtrosP2ga(String.valueOf(df1.format(yu  + gadaee)));
            bean.setPrestamo2(String.valueOf(prestamo.getCodigo()));
            
        }
    }
    return  bean ;
    }
