    public List listarMultas(String codigo, String fechaDesde, 
                                      String fechaHasta) {
           String mes = "";
           String ano = "";
           String mes2 = "";
           String ano2 = "";

           if (!fechaDesde.equals("")) {
               ano = fechaDesde.substring(0, 4);
               mes = fechaDesde.substring(5, 7);
           }


           if (!fechaHasta.equals("")) {
               ano2 = fechaHasta.substring(0, 4);
               mes2 = fechaHasta.substring(5, 7);
           }

           String sql = "";

           sql = "select * from f63_multa where ";
           
                   if(codigo!=null) {
           if (!codigo.equals("")) {
               sql = sql + "  f63_socio = " + codigo ;
           }
                   }

           if (!fechaDesde.equals("")) {
               sql = sql + " and YEAR(f63_periodo)  >= '" + ano + "'";

           }

           if (!fechaHasta.equals("")) {
               sql = sql + " and YEAR(f63_periodo)  <= '" + ano2 + "' ";

           }

           sql = sql + " order by f63_periodo desc ";

           try {
               System.out.println(sql);
               return jdbcTemplate.query(sql, new MultasMapper());

           } catch (final EmptyResultDataAccessException e) {
               return null;
           }
       }

