    protected class MultasMapper implements RowMapper {
          public Object mapRow(ResultSet rs, int rowNum) throws SQLException {

              DecimalFormatSymbols dfs = new DecimalFormatSymbols();
                      dfs.setDecimalSeparator('.');
                      dfs.setGroupingSeparator(',');
                      DecimalFormat df1 = new DecimalFormat("#0.00", dfs);
                      df1.setGroupingSize(3);

              MultaBean bean = new MultaBean();
             bean.setId(rs.getString(1));
              bean.setSocio(rs.getString(2));

              bean.setPeriodo(pasaFecha3(rs.getString(3)));
              bean.setMultaPropuesta(String.valueOf(df1.format(rs.getDouble(4))));
              bean.setMultaDefinitiva(String.valueOf(df1.format(rs.getDouble(5))));
              bean.setMultaSobregiro(String.valueOf(df1.format(rs.getDouble(6))));
              if (rs.getString(7) != null) {
                  bean.setFechaPago(pasaFecha(rs.getString(7)));
              }
              bean.setFormaPago(rs.getString(8));
              return bean;

          }
      }

